/* Tooltip styles */
.vendor-tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
  width: 420px;
  max-width: min(420px, 100vw - 40px);
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 12px 14px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
  z-index: 1000;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
  transform: translateY(4px);
  pointer-events: none;
  text-align: left;
  display: flex;
  flex-direction: column;
}

.vendor-tooltip::before {
  content: "";
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  height: 12px;
  background: transparent;
}

.bkt-vendor-pill:hover .vendor-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  pointer-events: auto;
}

.vendor-tooltip::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 30px;
  margin-left: -6px;
  border-width: 6px;
  border-style: solid;
  border-color: #0f172a transparent transparent transparent;
}

/* Flipped tooltip when close to the top */
.vendor-tooltip.pos-bottom {
  bottom: auto;
  top: calc(100% + 8px);
  transform: translateY(-4px);
}

.vendor-tooltip.pos-bottom::before {
  top: -12px;
  bottom: auto;
}

.vendor-tooltip.pos-bottom::after {
  top: auto;
  bottom: 100%;
  border-color: transparent transparent #0f172a transparent;
}

.bkt-vendor-pill:hover .vendor-tooltip.pos-bottom {
  transform: translateY(0);
}

