import React, { useState, useEffect, useMemo, useCallback, useRef } from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import ReactDOM from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm';

// ============================================================================
// APPSMITH HELPERS
// ============================================================================
const parseAppsmithModel = modelRaw => {
  if (!modelRaw) return {};
  let parsed = modelRaw;
  if (typeof modelRaw === 'string') {
    try {
      parsed = JSON.parse(modelRaw);
    } catch (e) {}
  }
  return parsed || {};
};
const safeShowAlert = (msg, type = 'info') => {
  if (window.appsmith?.showAlert) {
    window.appsmith.showAlert(msg, type);
  } else {
    console.log(`[Alert - ${type}] ${msg}`);
  }
};
const cleanVendorName = raw => (raw || '').replace(/^["'\s]+|["'\s]+$/g, '').trim();

// Check if an item exists in any group within a bucket list
const isItemInBuckets = (bucketList, itemId) => {
  const strId = String(itemId);
  return (bucketList || []).some(b => (b.lineItems || []).some(x => String(x.id) === strId));
};

// ============================================================================
// WORKSPACE COMPONENT: BucketVendorWorkspace
// ============================================================================
const BucketVendorWorkspace = React.memo(({
  aiBuckets = {},
  onProceed,
  isLocked = false,
  footerState = 'EDITABLE',
  allowCustomVendor = true,
  allowCustomGroup = true,
  vendorSearchResults = []
}) => {
  // Baseline hydration helper
  const getBucketsList = data => {
    if (!data || !Array.isArray(data.buckets)) return [];
    return data.buckets.map(b => ({
      ...b,
      originalName: b.originalName !== undefined ? b.originalName : b.name,
      originalDescription: b.originalDescription !== undefined ? b.originalDescription : b.description || '',
      originalVendorIds: b.originalVendorIds !== undefined ? b.originalVendorIds : (b.recommendedVendors || []).map(v => v.id),
      originalLineIds: b.originalLineIds !== undefined ? b.originalLineIds : (b.lineItems || []).map(l => l.id),
      group_type: b.group_type || 'AI recommended'
    }));
  };
  const getUnassignedList = data => data && Array.isArray(data.unassigned) ? data.unassigned : [];

  // Core State
  const [buckets, setBuckets] = useState(() => getBucketsList(aiBuckets));
  const [unassigned, setUnassigned] = useState(() => getUnassignedList(aiBuckets));
  const [selectedVendors, setSelectedVendors] = useState(() => {
    const init = {};
    getBucketsList(aiBuckets).forEach(b => {
      init[b.id] = {};
      let hasSelected = false;
      (b.recommendedVendors || []).forEach(v => {
        if (v.isSelected) {
          init[b.id][v.id] = true;
          hasSelected = true;
        }
      });
      if (!hasSelected && b.recommendedVendors?.[0]) {
        init[b.id][b.recommendedVendors[0].id] = true;
      }
    });
    return init;
  });

  // Group Management State
  const [showCreateBucket, setShowCreateBucket] = useState(false);
  const [newBucketName, setNewBucketName] = useState('');
  const [createBucketError, setCreateBucketError] = useState('');
  const [editingBucketId, setEditingBucketId] = useState(null);
  const [editingBucketName, setEditingBucketName] = useState('');
  const [editingBucketError, setEditingBucketError] = useState('');
  const [deletingBucketId, setDeletingBucketId] = useState(null);

  // Description / Rationale Edit State
  const [editingDescBucketId, setEditingDescBucketId] = useState(null);
  const [editingDescText, setEditingDescText] = useState('');

  // Vendor Search & Custom Vendor State
  const [addVendorBucketId, setAddVendorBucketId] = useState(null);
  const [customVendorName, setCustomVendorName] = useState('');
  const [customVendorError, setCustomVendorError] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  // Drag and Drop State & Refs
  const [draggedInfo, setDraggedInfo] = useState(null);
  const formContainerRef = useRef(null);
  const searchTimerRef = useRef(null);

  // Auto-scroll dropdown into view
  useEffect(() => {
    if (isDropdownOpen && formContainerRef.current) {
      const timer = setTimeout(() => {
        formContainerRef.current?.scrollIntoView({
          behavior: 'smooth',
          block: 'nearest'
        });
      }, 60);
      return () => clearTimeout(timer);
    }
  }, [isDropdownOpen, customVendorName]);

  // Dataset signature helper to prevent wiping out user edits on unrelated model updates
  const getDatasetSignature = useCallback(data => {
    if (!data || !data.buckets || data.buckets.length === 0) return '';
    try {
      return JSON.stringify({
        b: (data.buckets || []).map(b => ({
          id: b.id,
          lines: (b.lineItems || []).map(l => l.id),
          v: (b.recommendedVendors || []).map(v => v.id)
        })),
        u: (data.unassigned || []).map(u => u.id)
      });
    } catch (e) {
      return '';
    }
  }, []);
  const lastLoadedDatasetSigRef = useRef(getDatasetSignature(aiBuckets));
  useEffect(() => {
    if (!aiBuckets || !aiBuckets.buckets) return;
    const currentSig = getDatasetSignature(aiBuckets);
    if (!currentSig || lastLoadedDatasetSigRef.current === currentSig) return;
    lastLoadedDatasetSigRef.current = currentSig;
    const bList = getBucketsList(aiBuckets);
    const uList = getUnassignedList(aiBuckets);
    setBuckets(bList);
    setUnassigned(uList);
    const init = {};
    bList.forEach(b => {
      init[b.id] = {};
      let hasSelected = false;
      (b.recommendedVendors || []).forEach(v => {
        if (v.isSelected) {
          init[b.id][v.id] = true;
          hasSelected = true;
        }
      });
      if (!hasSelected && b.recommendedVendors?.[0]) {
        init[b.id][b.recommendedVendors[0].id] = true;
      }
    });
    setSelectedVendors(init);
  }, [aiBuckets, getDatasetSignature]);

  // --------------------------------------------------------------------------
  // LINE ITEM ALLOCATION HANDLERS (Mathematical Invariant Guaranteed)
  // --------------------------------------------------------------------------
  const handleDragStart = useCallback((e, item, sourceBucketId) => {
    if (isLocked) return;
    setDraggedInfo({
      item,
      sourceBucketId
    });
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', String(item.id));
  }, [isLocked]);
  const handleDragOver = useCallback(e => {
    e.preventDefault();
  }, []);
  const handleDropOnBucket = useCallback((e, targetBucketId) => {
    e.preventDefault();
    if (isLocked || !draggedInfo) return;
    const {
      item,
      sourceBucketId
    } = draggedInfo;
    if (sourceBucketId === targetBucketId) {
      setDraggedInfo(null);
      return;
    }
    if (sourceBucketId === 'unassigned') {
      setUnassigned(prev => prev.filter(x => String(x.id) !== String(item.id)));
      setBuckets(prev => prev.map(b => {
        if (b.id === targetBucketId) {
          if (b.lineItems.some(x => String(x.id) === String(item.id))) return b;
          return {
            ...b,
            lineItems: [...b.lineItems, item]
          };
        }
        return b;
      }));
    } else {
      setBuckets(prev => prev.map(b => {
        if (b.id === sourceBucketId) {
          return {
            ...b,
            lineItems: b.lineItems.filter(x => String(x.id) !== String(item.id))
          };
        }
        if (b.id === targetBucketId) {
          if (b.lineItems.some(x => String(x.id) === String(item.id))) return b;
          return {
            ...b,
            lineItems: [...b.lineItems, item]
          };
        }
        return b;
      }));
    }
    setDraggedInfo(null);
  }, [draggedInfo, isLocked]);
  const handleDropOnUnassigned = useCallback(e => {
    e.preventDefault();
    if (isLocked || !draggedInfo) return;
    const {
      item,
      sourceBucketId
    } = draggedInfo;
    if (sourceBucketId === 'unassigned') {
      setDraggedInfo(null);
      return;
    }
    setBuckets(prev => {
      const nextBuckets = prev.map(b => b.id === sourceBucketId ? {
        ...b,
        lineItems: b.lineItems.filter(x => String(x.id) !== String(item.id))
      } : b);

      // Check if item still exists in any other bucket
      if (!isItemInBuckets(nextBuckets, item.id)) {
        setUnassigned(prevU => {
          if (prevU.some(x => String(x.id) === String(item.id))) return prevU;
          return [...prevU, item];
        });
      } else {
        setUnassigned(prevU => prevU.filter(x => String(x.id) !== String(item.id)));
      }
      return nextBuckets;
    });
    setDraggedInfo(null);
  }, [draggedInfo, isLocked]);
  const handleAssignToBucket = useCallback((item, targetBucketId) => {
    if (isLocked) return;
    setUnassigned(prev => prev.filter(x => String(x.id) !== String(item.id)));
    setBuckets(prev => prev.map(b => {
      if (b.id === targetBucketId) {
        if (b.lineItems.some(x => String(x.id) === String(item.id))) return b;
        return {
          ...b,
          lineItems: [...b.lineItems, item]
        };
      }
      return b;
    }));
  }, [isLocked]);
  const handleRemoveFromBucket = useCallback((item, bucketId) => {
    if (isLocked) return;
    setBuckets(prev => {
      const nextBuckets = prev.map(b => b.id === bucketId ? {
        ...b,
        lineItems: b.lineItems.filter(x => String(x.id) !== String(item.id))
      } : b);

      // If item is no longer in any remaining bucket, return it to unassigned
      if (!isItemInBuckets(nextBuckets, item.id)) {
        setUnassigned(prevU => {
          if (prevU.some(x => String(x.id) === String(item.id))) return prevU;
          return [...prevU, item];
        });
      } else {
        setUnassigned(prevU => prevU.filter(x => String(x.id) !== String(item.id)));
      }
      return nextBuckets;
    });
  }, [isLocked]);

  // --------------------------------------------------------------------------
  // GROUP RENAME & DELETE HANDLERS (With Duplicate Line Guard)
  // --------------------------------------------------------------------------
  const handleStartRename = useCallback((bucketId, currentName) => {
    if (isLocked) return;
    setEditingBucketId(bucketId);
    setEditingBucketName(currentName);
    setEditingBucketError('');
  }, [isLocked]);
  const handleSaveRename = useCallback(bucketId => {
    const trimmed = editingBucketName.trim();
    if (!trimmed) {
      setEditingBucketError('Group name cannot be empty.');
      return;
    }
    const isDuplicate = buckets.some(b => b.id !== bucketId && b.name.toLowerCase() === trimmed.toLowerCase());
    if (isDuplicate) {
      setEditingBucketError('A group with this name already exists.');
      return;
    }
    setBuckets(prev => prev.map(b => b.id === bucketId ? {
      ...b,
      name: trimmed
    } : b));
    setEditingBucketId(null);
    setEditingBucketName('');
    setEditingBucketError('');
  }, [editingBucketName, buckets]);
  const handleCancelRename = useCallback(() => {
    setEditingBucketId(null);
    setEditingBucketName('');
    setEditingBucketError('');
  }, []);
  const handlePromptDeleteGroup = useCallback(bucketId => {
    if (isLocked) return;
    setDeletingBucketId(bucketId);
  }, [isLocked]);
  const handleCancelDeleteGroup = useCallback(() => {
    setDeletingBucketId(null);
  }, []);
  const handleConfirmDeleteGroup = useCallback(bucketId => {
    if (isLocked) return;
    const target = buckets.find(b => b.id === bucketId);
    if (!target) return;

    // Remaining buckets after this group is removed
    const remainingBuckets = buckets.filter(b => b.id !== bucketId);

    // CRITICAL: Only items that DO NOT exist in ANY remaining bucket become unassigned!
    // If an item was allocated to multiple groups, it remains safely in its other group(s).
    const orphanedItems = (target.lineItems || []).filter(item => !isItemInBuckets(remainingBuckets, item.id));
    if (orphanedItems.length > 0) {
      setUnassigned(prev => {
        const existingIds = new Set(prev.map(item => String(item.id)));
        const newOrphans = orphanedItems.filter(item => !existingIds.has(String(item.id)));
        return [...prev, ...newOrphans];
      });
    }
    setBuckets(remainingBuckets);

    // Clean up selectedVendors for the deleted bucket
    setSelectedVendors(prev => {
      const next = {
        ...prev
      };
      delete next[bucketId];
      return next;
    });
    setDeletingBucketId(null);
  }, [isLocked, buckets]);

  // --------------------------------------------------------------------------
  // SOURCING RATIONALE / DESCRIPTION HANDLERS
  // --------------------------------------------------------------------------
  const handleStartEditDesc = useCallback((bucketId, currentDesc) => {
    if (isLocked) return;
    setEditingDescBucketId(bucketId);
    setEditingDescText(currentDesc || '');
  }, [isLocked]);
  const handleSaveDesc = useCallback(bucketId => {
    const trimmed = editingDescText.trim();
    setBuckets(prev => prev.map(b => b.id === bucketId ? {
      ...b,
      description: trimmed
    } : b));
    setEditingDescBucketId(null);
    setEditingDescText('');
  }, [editingDescText]);
  const handleCancelEditDesc = useCallback(() => {
    setEditingDescBucketId(null);
    setEditingDescText('');
  }, []);

  // --------------------------------------------------------------------------
  // VENDOR SEARCH, SELECTION & DELETION HANDLERS
  // --------------------------------------------------------------------------
  const handleToggleVendor = useCallback((bucketId, vendorId) => {
    if (isLocked) return;
    setSelectedVendors(prev => {
      const current = prev[bucketId] || {};
      return {
        ...prev,
        [bucketId]: {
          ...current,
          [vendorId]: !current[vendorId]
        }
      };
    });
  }, [isLocked]);
  const handleDeleteVendor = useCallback((e, bucketId, vendorId) => {
    e.stopPropagation();
    e.preventDefault();
    if (isLocked) return;
    setBuckets(prev => prev.map(b => {
      if (b.id !== bucketId) return b;
      return {
        ...b,
        recommendedVendors: b.recommendedVendors.filter(v => v.id !== vendorId)
      };
    }));
    setSelectedVendors(prev => {
      const bucketSelections = {
        ...(prev[bucketId] || {})
      };
      delete bucketSelections[vendorId];
      return {
        ...prev,
        [bucketId]: bucketSelections
      };
    });
  }, [isLocked]);
  const handleViewResearch = useCallback((e, vendor) => {
    e.stopPropagation();
    e.preventDefault();
    const cleanId = parseInt(String(vendor.vendor_id || vendor.id || '').replace(/^V-/, ''), 10);
    window.appsmith?.updateModel?.({
      selectedResearchVendor: {
        id: vendor.id,
        vendor_id: !isNaN(cleanId) ? cleanId : null,
        name: vendor.name,
        sapVendorCode: vendor.sapVendorCode || '',
        aribaSupplierId: vendor.aribaSupplierId || ''
      }
    });
    window.appsmith?.triggerEvent?.('onIButtonClick');
  }, []);
  const handleSearchInput = useCallback(val => {
    setCustomVendorName(val);
    setCustomVendorError('');
    setIsDropdownOpen(true);
    const trimmed = val.trim();
    if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    if (trimmed.length >= 3) {
      searchTimerRef.current = setTimeout(() => {
        window.appsmith?.updateModel?.({
          vendorSearchTerm: trimmed
        });
        window.appsmith?.triggerEvent?.('onSearchVendor');
      }, 500);
    } else {
      window.appsmith?.updateModel?.({
        vendorSearchTerm: ''
      });
    }
  }, []);
  const handleClearSearch = useCallback(() => {
    setCustomVendorName('');
    setCustomVendorError('');
    if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    window.appsmith?.updateModel?.({
      vendorSearchTerm: ''
    });
  }, []);
  const handleSelectVendor = useCallback((bucketId, vendor) => {
    const vName = cleanVendorName(vendor.vendor_name || vendor.name);
    if (!vName) return;
    const targetBucket = buckets.find(b => b.id === bucketId);
    if (targetBucket?.recommendedVendors.some(v => v.name.toLowerCase() === vName.toLowerCase())) {
      setCustomVendorError('Vendor already exists in this group.');
      return;
    }
    const newVendor = {
      id: vendor.vendor_id ? 'V-' + vendor.vendor_id : 'V-CUST-' + Date.now(),
      vendor_id: vendor.vendor_id || null,
      name: vName,
      sapVendorCode: vendor.sap_vendor_code || '',
      aribaSupplierId: vendor.ariba_supplier_id || vendor.ariba_erp_vendor_id || '',
      isManual: true,
      justification: null
    };
    setBuckets(prev => prev.map(b => b.id === bucketId ? {
      ...b,
      recommendedVendors: [...b.recommendedVendors, newVendor]
    } : b));
    setSelectedVendors(prev => ({
      ...prev,
      [bucketId]: {
        ...(prev[bucketId] || {}),
        [newVendor.id]: true
      }
    }));
    setCustomVendorName('');
    setCustomVendorError('');
    setAddVendorBucketId(null);
    setIsDropdownOpen(false);
  }, [buckets]);
  const handleAddCustomVendor = useCallback(bucketId => {
    const raw = cleanVendorName(customVendorName);
    if (isLocked || !raw) return;
    const targetBucket = buckets.find(b => b.id === bucketId);
    if (targetBucket?.recommendedVendors.some(v => v.name.toLowerCase() === raw.toLowerCase())) {
      setCustomVendorError('Vendor already exists in this group.');
      return;
    }
    const newVendor = {
      id: 'V-CUST-' + Date.now(),
      name: raw,
      isManual: true,
      justification: null
    };
    setBuckets(prev => prev.map(b => b.id === bucketId ? {
      ...b,
      recommendedVendors: [...b.recommendedVendors, newVendor]
    } : b));
    setSelectedVendors(prev => ({
      ...prev,
      [bucketId]: {
        ...(prev[bucketId] || {}),
        [newVendor.id]: true
      }
    }));
    setCustomVendorName('');
    setCustomVendorError('');
    setAddVendorBucketId(null);
    setIsDropdownOpen(false);
  }, [customVendorName, isLocked, buckets]);
  const handleCreateBucket = useCallback(() => {
    const trimmedName = newBucketName.trim();
    if (isLocked || !trimmedName) return;
    if (buckets.some(b => b.name.toLowerCase() === trimmedName.toLowerCase())) {
      setCreateBucketError('A group with this name already exists.');
