	color: #2563EB;
	border-color: #93C5FD;
}

.bkt-rename-wrapper {
	display: flex;
	align-items: center;
	gap: 6px;
	position: relative;
	flex-wrap: wrap;
}

.bkt-rename-input {
	border: 1.5px solid #3B82F6;
	border-radius: 6px;
	padding: 4px 8px;
	font-size: 14px;
	font-weight: 600;
	color: #0F172A;
	outline: none;
	min-width: 220px;
	box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.bkt-rename-btn {
	border: none;
	border-radius: 6px;
	padding: 5px 10px;
	font-size: 12px;
	font-weight: 700;
