}

.bkt-rename-btn.cancel:hover {
	background: #E2E8F0;
	color: #0F172A;
}

.bkt-rename-error {
	width: 100%;
	color: #E11D48;
	font-size: 11.5px;
	font-weight: 600;
	margin-top: 2px;
}

.bkt-delete-group-btn {
	background: transparent;
	border: 1px solid #FECDD3;
	color: #E11D48;
	font-size: 11.5px;
	font-weight: 600;
	padding: 4px 10px;
	border-radius: 6px;
	cursor: pointer;
	display: inline-flex;
	align-items: center;
	gap: 5px;
	transition: all 0.15s ease;
	margin-left: auto;
}

.bkt-delete-group-btn:hover {
	background: #FFF1F2;
	border-color: #FB7185;
	color: #BE123C;
}

.bkt-delete-confirm-box {
