	gap: 8px;
	background: #FFF1F2;
	border: 1px solid #FDA4AF;
	border-radius: 6px;
	padding: 4px 10px;
	font-size: 12px;
	font-weight: 600;
	color: #9F1239;
	margin-left: auto;
}

.bkt-confirm-btn {
	background: #E11D48;
	color: #FFFFFF;
	border: none;
	border-radius: 4px;
	padding: 3px 8px;
	font-size: 11.5px;
	font-weight: 700;
	cursor: pointer;
	transition: background 0.15s ease;
}

.bkt-confirm-btn:hover {
	background: #BE123C;
}

.bkt-cancel-btn {
	background: #FFFFFF;
	color: #475569;
	border: 1px solid #CBD5E1;
	border-radius: 4px;
	padding: 3px 8px;
	font-size: 11.5px;
	font-weight: 600;
