}

.bkt-cancel-btn:hover {
	background: #F1F5F9;
}

/* Accented Group Description & Sourcing Rationale Card */
.bkt-description-card {
	background: #F8FAFC;
	border-left: 3px solid #3B82F6;
	border-radius: 0 8px 8px 0;
	padding: 10px 14px;
	margin-bottom: 14px;
}

.bkt-description-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 8px;
	margin-bottom: 5px;
}

.bkt-description-badge {
	display: inline-flex;
	align-items: center;
	gap: 5px;
	font-size: 10.5px;
	font-weight: 800;
	letter-spacing: 0.05em;
	color: #2563EB;
	text-transform: uppercase;
}

.bkt-description-text {
	font-size: 13px;
	color: #334155;
	line-height: 1.5;
}

.bkt-description-text.empty {
	color: #94A3B8;
	font-style: italic;
}

.bkt-edit-desc-trigger {
	background: transparent;
	border: none;
	color: #64748B;
	font-size: 11px;
	font-weight: 600;
	cursor: pointer;
	padding: 2px 6px;
	border-radius: 4px;
	transition: all 0.15s ease;
}

.bkt-edit-desc-trigger:hover {
	background: #E2E8F0;
	color: #1E293B;
}

.bkt-desc-textarea {
	width: 100%;
	box-sizing: border-box;
	border: 1.5px solid #3B82F6;
	border-radius: 6px;
	padding: 8px 10px;
	font-size: 13px;
	line-height: 1.45;
	color: #0F172A;
	resize: vertical;
	outline: none;
	background: #FFFFFF;
	box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.1);
}

.bkt-desc-actions {
	display: flex;
	align-items: center;
	gap: 8px;
	margin-top: 8px;
}

.bkt-section-label {
	font-size: 10px;
	font-weight: 800;
	color: #64748b;
	letter-spacing: 0.05em;
	margin-bottom: 8px;
	text-transform: uppercase;
}

.bkt-items-grid {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
	gap: 10px;
	margin-bottom: 20px;
}

.bkt-item-chip {
	background: #f8fafc;
	border: 1px solid #e2e8f0;
	border-radius: 6px;
	padding: 8px 10px;
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	cursor: grab;
	gap: 8px;
	min-width: 0;
	box-sizing: border-box;
}

.bkt-item-chip.has-duplicate {
	border-color: #f59e0b;
	background: #fffbeb;
}

.bkt-item-chip:hover {
	border-color: #cbd5e1;
	background: #f1f5f9;
}

.bkt-item-chip.has-duplicate:hover {
	border-color: #d97706;
	background: #fef3c7;
}

.bkt-chip-content {
	display: flex;
	flex-direction: column;
	gap: 3px;
	flex: 1 1 0%;
	min-width: 0;
	overflow: hidden;
}

.bkt-chip-name {
	font-size: 11px;
	font-weight: 700;
	color: #0f172a;
	line-height: 1.35;
	white-space: normal;
	word-break: break-word;
	overflow-wrap: anywhere;
}

.bkt-chip-meta {
	font-size: 10px;
	color: #64748b;
	font-weight: 500;
	white-space: normal;
	word-break: break-word;
	overflow-wrap: anywhere;
}

.bkt-item-delete {
	background: none;
	border: none;
	color: #94a3b8;
	cursor: pointer;
	padding: 3px;
	font-size: 13px;
	line-height: 1;
	border-radius: 4px;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	width: 22px;
	height: 22px;
	transition: all 0.15s ease;
	margin-top: -1px;
}

.bkt-item-delete:hover {
	color: #ef4444;
	background: #fee2e2;
}

.bkt-card-empty-hint {
