  const getUnassignedList = data => (data && Array.isArray(data.unassigned)) ? data.unassigned : [];

  // Core State
  const [buckets, setBuckets] = useState(() => getBucketsList(aiBuckets));
  const [unassigned, setUnassigned] = useState(() => getUnassignedList(aiBuckets));
