  useEffect(() => {
    if (isDropdownOpen && formContainerRef.current) {
      const timer = setTimeout(() => {
        formContainerRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }, 60);
      return () => clearTimeout(timer);
    }
  }, [isDropdownOpen, customVendorName]);

  // Dataset signature helper to prevent wiping out user edits on unrelated model updates
  const getDatasetSignature = useCallback(data => {
    if (!data || !data.buckets || data.buckets.length === 0) return '';
    try {
      return JSON.stringify({
        b: (data.buckets || []).map(b => ({
          id: b.id,
          lines: (b.lineItems || []).map(l => l.id),
          v: (b.recommendedVendors || []).map(v => v.id)
        })),
        u: (data.unassigned || []).map(u => u.id)
      });
    } catch (e) {
      return '';
    }
  }, []);

  const lastLoadedDatasetSigRef = useRef(getDatasetSignature(aiBuckets));

  useEffect(() => {
    if (!aiBuckets || !aiBuckets.buckets) return;
    const currentSig = getDatasetSignature(aiBuckets);
    if (!currentSig || lastLoadedDatasetSigRef.current === currentSig) return;
    lastLoadedDatasetSigRef.current = currentSig;

    const bList = getBucketsList(aiBuckets);
    const uList = getUnassignedList(aiBuckets);
    setBuckets(bList);
    setUnassigned(uList);

    const init = {};
    bList.forEach(b => {
      init[b.id] = {};
      let hasSelected = false;
      (b.recommendedVendors || []).forEach(v => {
        if (v.isSelected) {
          init[b.id][v.id] = true;
          hasSelected = true;
        }
