    const { item, sourceBucketId } = draggedInfo;
    if (sourceBucketId === targetBucketId) {
      setDraggedInfo(null);
      return;
    }

    if (sourceBucketId === 'unassigned') {
      setUnassigned(prev => prev.filter(x => String(x.id) !== String(item.id)));
      setBuckets(prev => prev.map(b => {
        if (b.id === targetBucketId) {
          if (b.lineItems.some(x => String(x.id) === String(item.id))) return b;
          return { ...b, lineItems: [...b.lineItems, item] };
        }
        return b;
      }));
    } else {
      setBuckets(prev => prev.map(b => {
        if (b.id === sourceBucketId) {
          return { ...b, lineItems: b.lineItems.filter(x => String(x.id) !== String(item.id)) };
        }
        if (b.id === targetBucketId) {
          if (b.lineItems.some(x => String(x.id) === String(item.id))) return b;
          return { ...b, lineItems: [...b.lineItems, item] };
        }
        return b;
      }));
    }
    setDraggedInfo(null);
  }, [draggedInfo, isLocked]);

  const handleDropOnUnassigned = useCallback(e => {
    e.preventDefault();
    if (isLocked || !draggedInfo) return;
    const { item, sourceBucketId } = draggedInfo;
    if (sourceBucketId === 'unassigned') {
      setDraggedInfo(null);
      return;
    }

    setBuckets(prev => {
      const nextBuckets = prev.map(b => b.id === sourceBucketId ? {
        ...b,
        lineItems: b.lineItems.filter(x => String(x.id) !== String(item.id))
      } : b);

      // Check if item still exists in any other bucket
      if (!isItemInBuckets(nextBuckets, item.id)) {
        setUnassigned(prevU => {
          if (prevU.some(x => String(x.id) === String(item.id))) return prevU;
          return [...prevU, item];
        });
      } else {
        setUnassigned(prevU => prevU.filter(x => String(x.id) !== String(item.id)));
      }
      return nextBuckets;
    });
    setDraggedInfo(null);
  }, [draggedInfo, isLocked]);

  const handleAssignToBucket = useCallback((item, targetBucketId) => {
    if (isLocked) return;
    setUnassigned(prev => prev.filter(x => String(x.id) !== String(item.id)));
    setBuckets(prev => prev.map(b => {
      if (b.id === targetBucketId) {
        if (b.lineItems.some(x => String(x.id) === String(item.id))) return b;
        return { ...b, lineItems: [...b.lineItems, item] };
      }
      return b;
    }));
  }, [isLocked]);

  const handleRemoveFromBucket = useCallback((item, bucketId) => {
    if (isLocked) return;
    setBuckets(prev => {
      const nextBuckets = prev.map(b => b.id === bucketId ? {
        ...b,
        lineItems: b.lineItems.filter(x => String(x.id) !== String(item.id))
      } : b);

