  const handleCancelDeleteGroup = useCallback(() => {
    setDeletingBucketId(null);
  }, []);

  const handleConfirmDeleteGroup = useCallback(bucketId => {
    if (isLocked) return;
    const target = buckets.find(b => b.id === bucketId);
    if (!target) return;

    // Remaining buckets after this group is removed
