// ============================================================================
// TOP LEVEL WORKFLOW BRIDGE: CustomVendorRecommendationHub
// ============================================================================
const emitVendorGroupsToWorkflow = (groups, modifiedJson) => {
  const modelPatch = {
    targetStageId: 'rfp_generation',
    transitionMode: 'advance',
    transitionPayload: {
      sourcingGroups: Array.isArray(groups) ? groups : [],
      modifiedJson: modifiedJson
    }
  };

  const trigger = () => {
    if (window.appsmith?.triggerEvent) {
      window.appsmith.triggerEvent('onProceedToRfp');
    }
  };

  if (window.appsmith?.updateModel) {
    Promise.resolve(window.appsmith.updateModel(modelPatch))
      .then(() => setTimeout(trigger, 0))
      .catch(() => setTimeout(trigger, 0));
  } else {
    trigger();
  }
};

function CustomVendorRecommendationHub() {
  const [modelData, setModelData] = useState(() => parseAppsmithModel(window.appsmith?.model));

  useEffect(() => {
    if (window.appsmith?.onModelChange) {
      window.appsmith.onModelChange(m => {
        if (!m) return;
        setModelData(parseAppsmithModel(m));
      });
    }
  }, []);

  const {
    aiBuckets = null,
    isLocked = false,
    footerState = 'EDITABLE',
    sessionActionState = null,
    allowCustomVendor = true,
    allowCustomGroup = true,
    vendorSearchResults = []
  } = modelData;

  const handleVendorsProceed = useCallback((groups, modifiedJson) => {
    if (window.appsmith?.updateModel) {
      window.appsmith.updateModel({ sessionActionState: 'SUBMITTING' });
    }
    emitVendorGroupsToWorkflow(groups, modifiedJson);
  }, []);

  const handleCloseModal = useCallback(() => {
    if (window.appsmith?.updateModel) {
      window.appsmith.updateModel({ sessionActionState: null });
    }
    window.appsmith?.triggerEvent?.('onCloseRfpModal');
  }, []);

  const handleRetry = useCallback(() => {
    if (window.appsmith?.updateModel) {
      window.appsmith.updateModel({ sessionActionState: 'SUBMITTING' });
    }
    window.appsmith?.triggerEvent?.('onRetryRfp');
  }, []);

  const renderSessionModal = () => {
    if (!sessionActionState) return null;
    return React.createElement('div', { className: 'vr-modal-overlay' },
      React.createElement('div', { className: 'vr-modal-box' },
        sessionActionState === 'SUBMITTING' && React.createElement(React.Fragment, null,
          React.createElement('div', { className: 'vr-modal-icon processing vr-icon-spin' }, '⏳'),
          React.createElement('h3', null, 'Generating RFQs...'),
          React.createElement('p', null, 'Please do not close this window.')
        ),
        sessionActionState === 'SUCCESS' && React.createElement(React.Fragment, null,
          React.createElement('div', { className: 'vr-modal-icon success' }, '✅'),
          React.createElement('h3', null, 'Successfully Queued!'),
          React.createElement('p', null, 'Your RFQs have been queued for generation.'),
          React.createElement('button', {
            className: 'vr-modal-btn primary',
            onClick: handleCloseModal
          }, 'Continue')
        ),
        sessionActionState === 'RETRY_PROMPT' && React.createElement(React.Fragment, null,
          React.createElement('div', { className: 'vr-modal-icon error' }, '⚠️'),
          React.createElement('h3', null, 'Generation Failed'),
          React.createElement('p', null, 'An error occurred while RFP Generation. Please retry. If problem persists please contact support.'),
          React.createElement('div', { className: 'vr-modal-actions' },
            React.createElement('button', {
              className: 'vr-modal-btn secondary',
              onClick: handleCloseModal
            }, 'Close'),
            React.createElement('button', {
              className: 'vr-modal-btn primary',
              onClick: handleRetry
            }, 'Retry Generation')
          )
        ),
        sessionActionState === 'FATAL_ERROR' && React.createElement(React.Fragment, null,
          React.createElement('div', { className: 'vr-modal-icon error' }, '⚠️'),
          React.createElement('h3', null, 'Request Failed'),
          React.createElement('p', null, 'The request failed permanently. Please contact the support team.'),
          React.createElement('button', {
            className: 'vr-modal-btn secondary',
            onClick: handleCloseModal
          }, 'Close')
        )
      )
    );
  };

  return React.createElement('div', { className: 'vr-widget-container' },
    renderSessionModal(),
    React.createElement(BucketVendorWorkspace, {
      aiBuckets,
      onProceed: handleVendorsProceed,
      isLocked,
      footerState,
      allowCustomVendor,
      allowCustomGroup,
      vendorSearchResults
    })
  );
}

appsmith.onReady(() => {
  ReactDOM.render(React.createElement(CustomVendorRecommendationHub, null), document.getElementById('root'));
});
